// Your website POSTs JSON, and n8n tucks it inside `body`.
// This node tidies the text and checks the required fields.

const incoming = $input.first().json;
const body = incoming.body || incoming;

const clean = (value) => (typeof value === 'string' ? value.trim() : '');

const name    = clean(body.name);
const email   = clean(body.email);
const phone   = clean(body.phone);
const product = clean(body.product) || 'Not specified';
const date    = clean(body.date);
const message = clean(body.message);

const emailLooksReal = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

const missing = [];
if (!name) missing.push('name');
if (!email) missing.push('email');
else if (!emailLooksReal) missing.push('a valid email');
if (!phone) missing.push('phone');

return [{
  json: {
    isValid: missing.length === 0,
    missing: missing.join(', '),
    receivedAt: new Date().toISOString(),
    receivedAtManila: new Date().toLocaleString('en-PH', { timeZone: 'Asia/Manila' }),
    name,
    email,
    phone,
    product,
    preferredDate: date || 'No preference given',
    message: message || '(no message left)'
  }
}];

